using System.Security.Cryptography;using System.Text;using System.Text.Json;using Diten.DecisionIntelligenceService.Application.Modules.OutcomeTracking;using Diten.DecisionIntelligenceService.Domain.Modules.OutcomeTracking;using Xunit;
public class ContractTests{static string Root(){var d=new DirectoryInfo(AppContext.BaseDirectory);while(d is not null&&!File.Exists(Path.Combine(d.FullName,"AGENTS.md")))d=d.Parent;return d!.FullName;}[Fact]public void Permission_manifest_is_exact(){var expected=new Dictionary<string,string>{{"outcome-tracking.outcomes.read","decision-intelligence.outcomes.read"},{"outcome-tracking.outcomes.create","decision-intelligence.outcomes.create"},{"outcome-tracking.outcomes.publish-version","decision-intelligence.outcomes.version"},{"outcome-tracking.outcomes.retire","decision-intelligence.outcomes.version"},{"outcome-tracking.measurements.append","decision-intelligence.measurements.append"},{"outcome-tracking.measurements.correct","decision-intelligence.measurements.correct"},{"outcome-tracking.decision-links.create","decision-intelligence.decision-links.manage"},{"outcome-tracking.decision-links.retire","decision-intelligence.decision-links.manage"},{"outcome-tracking.outcome-references.validate","decision-intelligence.outcome-references.validate"}};Assert.Equal(expected,AuthorizationManifest.Operations);Assert.DoesNotContain(AuthorizationManifest.Operations.Keys,x=>x!=x.Trim()||x.Any(char.IsUpper)||x.Contains('*'));}[Fact]public void Outcome_reference_has_five_fields()=>Assert.Equal(5,typeof(OutcomeReferenceV1).GetProperties().Length);
[Fact]public void Audit_raw_bytes_hash_hmac_and_rejections_are_exact(){var dir=Path.Combine(Root(),"execution/domains/enterprise-strategy-business-performance/module-packs/fixtures/MOD-0072/audit");var payload=File.ReadAllBytes(Path.Combine(dir,"outcome-tracking-audit-intent-submitted-v1.canonical.json"));Assert.Equal(246,payload.Length);var sha=Convert.ToHexString(SHA256.HashData(payload)).ToLowerInvariant();Assert.Equal("6e1e750ffddc6f65d45556e703b0aa282b8469dec00bcc516a7a0a5f823cc2a3",sha);Assert.Equal(sha+"\n",File.ReadAllText(Path.Combine(dir,"outcome-tracking-audit-intent-submitted-v1.canonical.sha256")));using var v=JsonDocument.Parse(File.ReadAllBytes(Path.Combine(dir,"outcome-tracking-audit-intent-submitted-v1.signing-vector.json")));var r=v.RootElement;string[] names=["scheme","eventId","eventName","eventVersion","tenantId","correlationId","producer","causationId","occurredAtUtc","canonicalPayloadByteLength"];var input=string.Join("\n",names.Select(n=>r.GetProperty(n).ToString()))+"\n";var h=new HMACSHA256(Encoding.UTF8.GetBytes(r.GetProperty("testOnlyKeyUtf8").GetString()!));var sig=Convert.ToHexString(h.ComputeHash(Encoding.UTF8.GetBytes(input).Concat(payload).ToArray())).ToLowerInvariant();Assert.Equal("0336b3630d4fa5e10c01cb7674681014d1a6e0d6df40ff3923b4555a9be3c07f",sig);using var reject=JsonDocument.Parse(File.ReadAllBytes(Path.Combine(dir,"outcome-tracking-audit-intent-submitted-v1.production-validator-rejection.json")));Assert.Equal(9,reject.RootElement.GetProperty("cases").GetArrayLength());var disposition=reject.RootElement.GetProperty("expectedDispositionForEveryCase");Assert.True(disposition.GetProperty("terminalSecurityFailure").GetBoolean());Assert.False(disposition.GetProperty("auditEventCreated").GetBoolean());Assert.False(disposition.GetProperty("retry").GetBoolean());}
[Fact]public void Ppm_wrapper_is_exact_and_no_copy(){var nested=new OutcomeReferenceV1(OutcomeReferenceV1.Name,OutcomeReferenceV1.Version,Guid.NewGuid(),Guid.NewGuid(),1);var wrapper=new BenefitCommitmentOutcomeReferenceV1(BenefitCommitmentOutcomeReferenceV1.Name,BenefitCommitmentOutcomeReferenceV1.Version,Guid.NewGuid(),nested).Validate();Assert.Equal(4,typeof(BenefitCommitmentOutcomeReferenceV1).GetProperties().Length);Assert.Equal(5,wrapper.OutcomeReference.GetType().GetProperties().Length);var json=JsonSerializer.Serialize(wrapper);foreach(var forbidden in new[]{"actualValue","measurement","period","evidence","realizationState"})Assert.DoesNotContain(forbidden,json,StringComparison.OrdinalIgnoreCase);}
[Theory][InlineData(ReferenceMode.HistoricalResolve,true,true,200)][InlineData(ReferenceMode.NewReferenceEligibility,true,false,200)][InlineData(ReferenceMode.NewReferenceEligibility,true,true,409)][InlineData(ReferenceMode.CurrentSelectionEligibility,true,false,400)][InlineData(ReferenceMode.HistoricalResolve,false,false,404)]public void Reference_modes_are_exact(ReferenceMode mode,bool visible,bool retired,int expected)=>Assert.Equal(expected,OutcomeReferencePolicy.Evaluate(mode,visible,retired));
